"use client";

import React, { useState, useEffect } from "react";
import Image from "next/image";

const MainApp: React.FC = () => {
  const [daysTogether, setDaysTogether] = useState(0);
  const anniversaryDate = new Date("2024-01-01T00:00:00");

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      const diff = now.getTime() - anniversaryDate.getTime();
      setDaysTogether(Math.floor(diff / (1000 * 60 * 60 * 24)));
    }, 1000);
    return () => clearInterval(timer);
  }, [anniversaryDate]);

  return (
    <div className="max-w-4xl mx-auto px-6 py-12 animate-fade-in-scale select-none">
      {/* Header & Counter */}
      <div className="flex flex-col items-center mb-16 text-center">
        <div className="relative w-40 h-40 mb-6 group cursor-pointer transition-transform duration-300 hover:scale-105 active:scale-95">
          <Image
            src="/couple_celebrate.png"
            alt="Celebrating"
            fill
            className="object-contain animate-bounce-subtle"
          />
          <div className="absolute -top-4 -right-4 bg-white/60 p-2 rounded-full shadow-sm">
            💖
          </div>
        </div>
        <h1 className="text-4xl font-bold text-mocha mb-2 italic">Our Journey Together</h1>
        <div className="glass-card px-8 py-4 mt-4 inline-block">
          <p className="text-mocha/80 text-sm uppercase tracking-widest mb-1">Days of Love</p>
          <span className="text-5xl font-black text-mocha tabular-nums">{daysTogether}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
        {/* Story Timeline */}
        <section className="space-y-8">
          <h2 className="text-2xl font-semibold text-mocha border-b-2 border-primary-pink inline-block pb-1">Our Story</h2>
          <div className="space-y-12 pl-4 border-l-2 border-primary-pink/30 relative">
            <Milestone
              title="First Meeting ☕"
              date="Jan 1, 2024"
              description="It all started with a simple 'Hi' and a lot of coffee."
              img="/couple_hug.png"
            />
            <Milestone
              title="The First Trip 🏔️"
              date="Feb 14, 2024"
              description="Exploring the mountains and making memories under the stars."
              img="/couple_blush.png"
            />
            <Milestone
              title="Official! 💍"
              date="Mar 30, 2024"
              description="When we knew this was forever. The happiest day."
              img="/couple_celebrate.png"
            />
          </div>
        </section>

        {/* Memory Gallery */}
        <section className="space-y-8">
          <h2 className="text-2xl font-semibold text-mocha border-b-2 border-primary-pink inline-block pb-1">Memories</h2>
          <div className="grid grid-cols-2 gap-4">
            <Polaroid src="/couple_hug.png" caption="Comfort" />
            <Polaroid src="/couple_blush.png" caption="Quiet Moments" />
            <Polaroid src="/couple_celebrate.png" caption="Laughter" />
            <Polaroid src="/couple_hug.png" caption="Always You" rotation="rotate-2" />
          </div>

          <div className="mt-12 glass-card p-6 border-dashed border-2 border-mocha/20">
            <h3 className="text-lg font-medium text-mocha mb-4 flex items-center gap-2">
              Love Notes 💌
            </h3>
            <div className="space-y-4">
              <LoveNote text="You're my favorite human." sender="M" side="left" />
              <LoveNote text="And you're my favorite bear! 🐻" sender="Y" side="right" />
              <LoveNote text="I love you more than pizza." sender="M" side="left" />
            </div>
          </div>
        </section>
      </div>

      {/* Secret Section */}
      <div className="mt-20 py-12 text-center border-t border-primary-pink/20">
        <p className="text-mocha/40 text-xs italic">Psst... I have a secret for you. Click the heart below.</p>
        <button className="mt-4 text-3xl hover:scale-125 transition-transform duration-300 active:scale-90">
          💝
        </button>
      </div>
    </div>
  );
};

const Milestone = ({ title, date, description, img }: any) => (
  <div className="relative pl-8 group">
    <div className="absolute -left-[9px] top-1 w-4 h-4 rounded-full bg-primary-pink border-4 border-white shadow-sm ring-4 ring-primary-pink/20" />
    <span className="text-xs text-mocha/50 font-medium uppercase tracking-wider">{date}</span>
    <h3 className="text-xl font-bold text-mocha mt-1">{title}</h3>
    <p className="text-mocha/70 mt-2 leading-relaxed text-sm">{description}</p>
    <div className="mt-4 w-20 h-20 relative opacity-0 group-hover:opacity-100 transition-opacity duration-500">
      <Image src={img} alt="Milestone sticker" fill className="object-contain" />
    </div>
  </div>
);

const Polaroid = ({ src, caption, rotation = "-rotate-1" }: any) => (
  <div className={`bg-white p-3 shadow-md hover:shadow-xl transition-all duration-300 transform hover:scale-105 active:scale-95 cursor-pointer ${rotation}`}>
    <div className="relative aspect-square overflow-hidden bg-gray-100">
      <Image src={src} alt="Memory" fill className="object-cover" />
    </div>
    <p className="text-center font-serif text-mocha/60 text-sm mt-3 italic">{caption}</p>
  </div>
);

const LoveNote = ({ text, sender, side }: any) => (
  <div className={`flex ${side === "right" ? "justify-end" : "justify-start"}`}>
    <div className={`max-w-[80%] px-4 py-2 rounded-2xl shadow-sm text-sm ${
      side === "right" ? "bg-primary-pink text-mocha rounded-br-none" : "bg-white text-mocha rounded-bl-none"
    }`}>
      {text}
      <span className="block text-[10px] mt-1 opacity-50 font-bold">{sender}</span>
    </div>
  </div>
);

export default MainApp;
