"use client";

import { useState } from "react";
import LockScreen from "@/components/LockScreen";
import MainApp from "@/components/MainApp";

export default function Home() {
  const [isUnlocked, setIsUnlocked] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);

  return (
    <main className="min-h-screen relative overflow-hidden">
      {/* Background Musical Toggle (Top Corner) */}
      <button
        onClick={() => setIsPlaying(!isPlaying)}
        className="fixed top-6 right-6 z-50 w-12 h-12 glass-card rounded-full flex items-center justify-center text-xl hover:scale-110 active:scale-95 transition-all duration-300 shadow-sm"
      >
        {isPlaying ? "🎵" : "🔇"}
        {isPlaying && (
          <span className="absolute -top-1 -right-1 flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary-pink opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-primary-pink"></span>
          </span>
        )}
      </button>

      {/* Conditional Rendering */}
      {!isUnlocked ? (
        <div className="animate-fade-in-scale">
          <LockScreen onUnlocked={() => setIsUnlocked(true)} />
        </div>
      ) : (
        <div className="animate-fade-in-scale">
          <MainApp />
        </div>
      )}

      {/* Decorative Ornaments (Subtle) */}
      <div className="fixed bottom-0 left-0 w-32 h-32 opacity-20 pointer-events-none">
        <div className="absolute inset-0 bg-primary-pink blur-3xl rounded-full" />
      </div>
      <div className="fixed top-0 right-0 w-48 h-48 opacity-10 pointer-events-none">
        <div className="absolute inset-0 bg-accent-peach blur-3xl rounded-full" />
      </div>
    </main>
  );
}
