"use client";

import React, { useState, useEffect } from "react";
import Image from "next/image";

interface LockScreenProps {
  onUnlocked: () => void;
}

const LockScreen: React.FC<LockScreenProps> = ({ onUnlocked }) => {
  const [passcode, setPasscode] = useState<string[]>([]);
  const [isError, setIsError] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const correctCode = "122222";

  const handleKeyPress = (num: string) => {
    if (passcode.length < 6 && !isSuccess) {
      const newPasscode = [...passcode, num];
      setPasscode(newPasscode);
    }
  };

  const handleDelete = () => {
    if (passcode.length > 0 && !isSuccess) {
      setPasscode(passcode.slice(0, -1));
    }
  };

  useEffect(() => {
    if (passcode.length === 6) {
      if (passcode.join("") === correctCode) {
        setIsSuccess(true);
        setTimeout(() => {
          onUnlocked();
        }, 800);
      } else {
        setIsError(true);
        setTimeout(() => {
          setPasscode([]);
          setIsError(false);
        }, 600);
      }
    }
  }, [passcode, onUnlocked]);

  return (
    <div className="flex flex-col items-center justify-center min-vh-100 p-4 select-none">
      {/* Top Section */}
      <div className="flex flex-col items-center mb-12 animate-fade-in-scale">
        <div className="relative w-32 h-32 mb-4">
          <Image
            src={isSuccess ? "/couple_celebrate.png" : isError ? "/couple_blush.png" : "/couple_hug.png"}
            alt="Cute Couple"
            fill
            className={`object-contain transition-transform duration-300 ${isSuccess ? 'scale-110' : 'animate-bounce-subtle'}`}
          />
        </div>
        <h1 className="text-2xl font-semibold text-mocha tracking-tight">
          {isSuccess ? "Welcome back! 💖" : isError ? "Oops! Not our code 😢" : "Enter Our Secret Code 💖"}
        </h1>
      </div>

      {/* Passcode Display */}
      <div className={`flex gap-4 mb-16 ${isError ? "animate-shake" : ""}`}>
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <div
            key={i}
            className={`w-4 h-4 rounded-full border-2 border-mocha/30 transition-all duration-200 transform ${
              passcode.length > i ? "bg-mocha scale-110 border-mocha" : "bg-transparent"
            } ${isSuccess ? "bg-green-400 border-green-400" : isError ? "bg-red-400 border-red-400" : ""}`}
          />
        ))}
      </div>

      {/* Numpad */}
      <div className="grid grid-cols-3 gap-6 max-w-xs w-full animate-fade-in-scale">
        {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((num) => (
          <NumpadButton key={num} value={num.toString()} onClick={() => handleKeyPress(num.toString())} />
        ))}
        <div /> {/* Empty space for alignment */}
        <NumpadButton value="0" onClick={() => handleKeyPress("0")} />
        {passcode.length > 0 && (
          <button
            onClick={handleDelete}
            className="flex items-center justify-center text-mocha/60 hover:text-mocha transition-colors text-lg"
          >
            ⌫
          </button>
        )}
      </div>

      <style jsx>{`
        .min-vh-100 { min-height: 100vh; }
      `}</style>
    </div>
  );
};

const NumpadButton = ({ value, onClick }: { value: string; onClick: () => void }) => (
  <button
    onClick={onClick}
    className="w-16 h-16 rounded-full glass-card flex items-center justify-center text-2xl font-medium text-mocha active:scale-90 active:bg-white/80 transition-all duration-150 shadow-sm hover:bg-white/40"
  >
    {value}
  </button>
);

export default LockScreen;
